delete from public.sections where page_id = (select id from public.pages where slug = '/industries');
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Industries","heading":"The Method Doesn''t Change With the Industry","body":"Eight sectors, one approach. What changes between them is the search language, not the work.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 0 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'grid', 'industryGrid', 'surface', '{"eyebrow":"Where JMC Works","heading":"Eight Industries, Two Kinds of Buyer","body":"The grouping below is descriptive. It says who a business sells to, and nothing about which service it needs.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","body":"Trades and home service businesses that get found at the moment something breaks.","icon":"wrench","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","body":"Practices and clinics where patients choose from a short list and book an appointment.","icon":"heart-pulse","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","body":"Places people plan a visit to, from an evening out to a weekend away.","icon":"utensils","href":"/industries/hospitality-attractions"},{"title":"Professional Services","body":"Firms whose clients compare a shortlist before they ever make contact.","icon":"briefcase","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","body":"Suppliers and service firms selling into plants, operators and procurement teams.","icon":"lightning","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","body":"Port, freight and marine operators whose customers are other businesses.","icon":"ship","href":"/industries/maritime-logistics"},{"title":"Commercial Construction & Infrastructure","body":"Contractors, civil firms and suppliers working on commercial and public projects.","icon":"hard-hat","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","body":"Manufacturers, service providers and suppliers in a heavily qualified supply chain.","icon":"plane","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method doesn''t change with the industry. If yours isn''t listed, it almost certainly still applies.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 1 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'the-method', 'featureSplit', 'white', '{"align":"left","eyebrow":"Pillar","heading":"What Stays the Same, and What Doesn''t","body":"The work is the same regardless of sector. The same audit, the same technical foundation, the same content approach, the same reporting. What changes is the search language buyers use, how long they take to decide, and what a single lead is worth.\n\nThat is a deliberate position rather than a gap. A specialist charges for pattern-matching from other clients in your sector, and JMC does not claim to have that yet. What it offers instead is a method that transfers, run on two tracks depending on whether a business competes in a defined area or across markets.","tableHeadings":["Stays the same","Varies by industry"],"tableRows":[{"cells":["Audit and technical foundation","The search language buyers actually use"]},{"cells":["On-page and content approach","How long the buying cycle runs"]},{"cells":["Reporting and recap structure","What a single lead is worth"]}],"groups":[],"cta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 2 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, whatever the industry.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 3 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Industry Questions","items":[{"question":"Does JMC specialise in a particular industry?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC cannot honestly offer yet. What it offers instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."},{"question":"What if an industry isn''t listed here?","answer":"The method still applies. The eight above are the sectors most common around the Houston area, not a list of what JMC is willing to work on. A visibility review is the fastest way to find out how the approach lands in yours."},{"question":"Which service fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local SEO, however many locations it runs. A business competing across markets or service lines is Traditional SEO."},{"question":"Does the industry change the price?","answer":"No. The packages are the same across every industry. Scope is what produces a custom quote, and scope is about reach and volume rather than sector."},{"question":"Does the industry change the work?","answer":"The priorities and the search language shift, sometimes a great deal. The method and the reporting do not."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/industries';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 5 from public.pages where slug = '/industries';
update public.sections set data = '{"eyebrow":"SEO for local, regional, and industrial businesses","heading":"Search Visibility, Explained Every Month.","body":"Jordan Marketing Consultants does one thing: search visibility for local, regional, and industrial businesses. Every month you get a plain recap of what was done, why, and what changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"},"showcase":[{"kind":"report","label":"Every month","title":"Monthly Recap","items":["What was done","Why it matters","What changed","What comes next"]},{"kind":"coverage","label":"Where you appear","title":"Search Visibility","items":["Search","Maps","Local grid"]},{"kind":"roadmap","label":"The plan","title":"SEO Roadmap","items":["Priorities set","Content queued","Technical fixes tracked"]}]}'::jsonb where key = 'hero' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Growth Paths","heading":"Two Paths, Sorted by Where You Compete","body":"Different businesses need different SEO strategies. Which one fits comes down to reach: a defined area, or several markets at once.","columns":2,"cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses that need stronger visibility in Google Search, Google Maps, and local service-area searches.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"trending-up","body":"For regional, national, and industry-focused companies competing across larger search markets.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb where key = 'growth-paths' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"treatment":"statement","heading":"No Mystery SEO. No Confusing Reports. No Guessing What You Paid For.","body":"Most agencies keep the work behind a login and the reasoning to themselves. JMC does the opposite. You see what was done, why it was done, and what it changed, in language that does not need translating. That is how the work is run, not a reporting add-on.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb where key = 'transparency' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Services","heading":"SEO Work Built Around Strategy, Visibility, and Accountability","body":"JMC focuses on the pieces of SEO that help businesses become easier to find, easier to understand, and easier to trust in search.","columns":3,"cards":[{"title":"SEO Strategy","icon":"target","body":"Keyword priorities, search intent, competitor visibility, and roadmap planning."},{"title":"Local Optimization","icon":"map-pin","body":"Local search improvements that support visibility in Google Search, Google Maps, and service-area searches."},{"title":"Google Business Profile Support","icon":"star","body":"Profile optimization, post strategy, service alignment, and activity that supports local trust."},{"title":"SEO Content Planning","icon":"file-text","body":"Strategic SEO pages, content roadmaps, service page improvements, and search-focused messaging."},{"title":"Technical SEO Monitoring","icon":"wrench","body":"Ongoing review of technical issues that can affect crawling, indexing, visibility, and site performance."},{"title":"Reporting and Monthly Recaps","icon":"bar-chart","body":"Clear monthly updates that explain progress, priorities, and next steps without burying you in jargon."}],"cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb where key = 'services' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"Industries","heading":"Where This Method Gets Pointed","body":"One method, aimed at two different kinds of search problem.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","icon":"wrench","body":"Roofers, plumbers, electricians, and the trades that live on calls from a service area.","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","icon":"heart-pulse","body":"Practices and clinics where people check credibility before they ever call.","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","icon":"utensils","body":"Venues, parks, and places people search for by what they want to do, not by name.","href":"/industries/hospitality-attractions"},{"title":"Professional Services","icon":"briefcase","body":"Firms whose next client is comparing three local options in a single sitting.","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","icon":"factory","body":"Operators and suppliers selling technical capability to a small, specific buyer pool.","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","icon":"network","body":"Port, freight, and supply chain businesses working across regions rather than a radius.","href":"/industries/maritime-logistics"},{"title":"Commercial Construction","icon":"hard-hat","body":"Contractors and infrastructure firms bidding well outside one city.","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","icon":"compass","body":"Suppliers and services in a market where the search volume is low and the intent is high.","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method does not change with the industry. If yours is not listed, it probably still applies.","cta":{"label":"Explore Industries","href":"/industries"}}'::jsonb where key = 'industries' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"Clear Reporting","heading":"What You Get Every Month","body":"SEO should not feel vague. Every month you get the same four answers, in the same order, in language that does not need a glossary.","did":"A plain summary of the SEO work completed: content, technical checks, local visibility tasks, and everything else inside the scope.","why":"The reasoning behind each piece of work, and how it supports visibility, relevance, or trust.","changed":"What moved, what did not, and what is still being watched.","next":"The priorities for the coming month, in order, so you always know where the campaign is heading.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb where key = 'monthly-recap' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Packages","heading":"SEO Options Built for Different Growth Stages","body":"JMC offers structured SEO options for businesses that need ongoing monthly support or a focused starting point before moving into a longer campaign.","columns":3,"cards":[{"title":"Monthly Local SEO","icon":"map-pin","meta":"From $875/mo","body":"For businesses that need consistent local visibility support across search, maps, content, reviews, and reporting.","cta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"}},{"title":"Monthly Traditional SEO","icon":"trending-up","meta":"From $2,295/mo","body":"For businesses targeting regional, national, or competitive industry visibility with a larger search footprint.","cta":{"label":"View Traditional SEO Packages","href":"/monthly-seo-packages#traditional"}},{"title":"Launch Sprints","icon":"compass","meta":"From $799 one-time","body":"For businesses that need a fixed-scope SEO foundation before deciding on monthly service.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}]}'::jsonb where key = 'packages' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"How It Works","heading":"A Clear SEO Process From Review to Recap","body":"SEO works better when the process is organized. JMC keeps the work focused around visibility, priorities, implementation, and clear communication.","steps":[{"title":"Visibility Review","body":"JMC reviews where your business currently shows up, where visibility is weak, and which opportunities are worth prioritizing."},{"title":"SEO Roadmap","body":"The work is organized around keyword priorities, content needs, local visibility, technical issues, and business goals."},{"title":"Implementation","body":"JMC completes the scoped SEO work, content updates, local optimization, and technical improvements tied to the plan."},{"title":"Monthly Recap","body":"You receive a clear summary of what was completed, what changed, and what should happen next."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb where key = 'process' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"heading":"Not Sure Where Your SEO Is Stuck? Start with a Visibility Review.","body":"A review identifies visibility gaps, priority opportunities, and the best next step for your business, market, and goals.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb where key = 'final-cta' and page_id = (select id from public.pages where slug = '/');
update public.pages set seo_title = 'Houston-Area SEO Agency | Jordan Marketing Consultants', meta_description = 'Houston-area SEO from Jordan Marketing Consultants. Local and traditional SEO, content planning, and a plain monthly recap of what changed, and why it did.' where slug = '/';
